``` astro-code
type Skill = BaseEntity & {
  // Existing
  skillId: string;
  version: string;
  approvalStatus: SkillApprovalStatus;
  lifecycleStatus: SkillLifecycleStatus;
  supersedesId?: string;
  source: SkillSource;       // now includes "message_derived"
  confidence?: number;
  spec: string;              // SKILL.md content
  resources?: Record<string, string>;
  scopeRelationshipId?: string;

  // NEW — message derivation tracking
  sourceTurnIds?: string[];        // turns used for derivation
  sourceRevisionIds?: string[];    // message revisions (deletion guarantee)
  sourceSessionId?: string;        // session-end extraction provenance
  dedupOfSkillId?: string;         // set when Dreamer proposes an update
  derivationContext?: {
    userInstruction?: string;      // user's guidance to LLM
    originalContent: string;       // raw message content used
    refinementModel: string;       // model used for refinement
  };
};
```
